// Use only the pinned public runtime and sales generated by this fixture.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdtempSync, mkdirSync, cpSync, rmSync, realpathSync, existsSync, renameSync } from 'node:fs';
import { join } from 'node:path';
import { randomBytes, createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { DatabaseSync } from 'node:sqlite';
import { openReplay } from '../waitron-adapter.mjs';
import { withOwnershipDiagnostics } from './ownership-diagnostics.mjs';
import { withStreamResultDiagnostics } from './stream-result-diagnostics.mjs';
import { withLocalCommandDiagnostics } from './local-command-diagnostics.mjs';
const controller = await import('../isolated-replay.mjs').catch(error => {
  if (error.code === 'ERR_MODULE_NOT_FOUND' && error.url === new URL('../isolated-replay.mjs', import.meta.url).href) return {};
  throw error;
});
const prepared = JSON.parse(readFileSync(process.env.COST_SYNTHETIC_CONFIG, 'utf8'));
const config = { localEndpoints: { s3: 'http://s3:8333', postgres: 'postgresql://fixture:fixture@postgres:5432/fixture',
  smtp: 'smtp://mailpit:1025', fiscal: 'http://fiscal:8080', gateway: 'https://gateway:443' },
  senders: { fiscal: 'disabled', mail: 'capture', acme: 'disabled', dns: 'disabled' } };
const initial = { taxpayer: { country: 'ES', taxId: '12345678Z', legalName: 'Synthetic SL' },
  location: { name: 'Synthetic venue', invoiceLocales: ['es'], operationDescription: 'Servicio',
    timeZone: 'Europe/Madrid', dayCutover: '06:00:00' },
  nodeName: 'Synthetic node', seriesCode: 'R', fullSeriesCode: 'F', idSistemaInformatico: 'WR' };
const docker = argv => execFileSync('docker', argv, { env: { PATH: process.env.PATH, LANG: 'C', TZ: 'UTC' },
  encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'pipe'] }).trim();
const fingerprint = database => ['', '-wal', '-shm'].map(suffix => existsSync(database + suffix)
  ? createHash('sha256').update(readFileSync(database + suffix)).digest('hex') : null);
const bad = { message: 'Invalid isolated cloud cost replay' };
async function fixture(t) {
  assert.equal(typeof controller.runIsolatedReplay, 'function', 'join isolated copying, replay and owned cleanup');
  const parent = realpathSync(mkdtempSync(join(prepared.stateParent, 'isolated-controller-')));
  const source = join(parent, 'source'), root = join(parent, 'owned');
  for (const path of [source, root]) mkdirSync(path, { mode: 0o700 });
  const token = randomBytes(32).toString('hex'), journal = { token, path: join(root, 'journal.json') };
  writeFileSync(join(root, '.cloud-cost-owner'), token, { mode: 0o600 });
  writeFileSync(journal.path, JSON.stringify({ schemaVersion: 1, source, root, ownershipToken: token }), { mode: 0o600 });
  const codeRoot = join(root, 'code'); cpSync(prepared.codeRoot, codeRoot, { recursive: true });
  let replay;
  t.after(async () => {
    await replay?.close();
    // Failure recovery is scoped to this fixture's fresh token and its exact resource IDs.
    for (const id of docker(['ps', '-aq', '--no-trunc', '--filter', 'label=io.waitron.cloud-cost.owner=' + token]).split('\n').filter(Boolean)) docker(['rm', '-f', '-v', id]);
    for (const id of docker(['network', 'ls', '-q', '--filter', 'label=io.waitron.cloud-cost.owner=' + token]).split('\n').filter(Boolean)) docker(['network', 'rm', id]);
    rmSync(parent, { recursive: true });
  });
  replay = await openReplay({ codeRoot: prepared.codeRoot, stateRoot: source, config, initial });
  for (const [n, at] of ['2026-01-01T12:00:00.000Z', '2026-01-02T12:00:00.000Z',
    '2026-01-02T12:00:01.000Z', '2026-01-02T12:00:02.000Z'].entries()) {
    const instant = new Date(at);
    await replay.recordSale({ origin: { source: 'operator_script', deviceId: null }, locale: 'es', invoiceLocales: ['es'], total: '12.10',
      lines: [{ lineNo: 1, name: 'PRIVATE_SYNTHETIC_ITEM_' + n, descriptions: { es: 'Artículo' }, quantity: '1',
        unitPrice: '10.00', vatRate: '21.00', lineTotal: '10.00' }],
      clock: { now: () => ({ instant, offsetMinutes: 60, confident: true, confidence: 'anchored', anchorAgeSeconds: 0 }) },
      settlement: { kind: 'immediate', tenders: [{ method: 'cash', amount: '12.10', tipAmount: '0', settledAt: instant }] } });
  }
  const database = join(source, 'venue/venue.db'); let locationId;
  const db = new DatabaseSync(database, { readOnly: true });
  try { locationId = db.prepare('SELECT id FROM locations').get().id; } finally { db.close(); }
  // Keep the generated WAL source active; dormant WAL sources are deliberately refused.
  writeFileSync(join(root, 'unrelated-sentinel'), 'keep caller state', { mode: 0o600 });
  return { source, root, journal, codeRoot, database, locationId, config: structuredClone(config), initial: structuredClone(initial),
    expected: { sales: 4, paid: 4, tradingDays: 2, busiest: 3 }, originalInventory: { timeZone: 'Europe/Madrid', days: 2, busiest: 3 },
    cadence: { mode: 'accelerated', factor: 100 }, replayWindowSeconds: 10, windowSeconds: 120,
    image: docker(['image', 'inspect', 'node:26.11.1-slim', '--format', '{{.Id}}']) };
}
function clean(f, before) {
  assert.deepEqual(fingerprint(f.database), before, 'original database and sidecars stay unchanged');
  assert.equal(readFileSync(join(f.root, 'unrelated-sentinel'), 'utf8'), 'keep caller state');
  for (const path of ['isolated-replay', 'venue-copy.db']) assert.equal(existsSync(join(f.root, path)), false, 'remove owned private state: ' + path);
  assert.equal(existsSync(join(f.codeRoot, 'cloud-cost-runner')), false, 'remove only the added controller code');
  assert.equal(docker(['ps', '-aq', '--filter', 'label=io.waitron.cloud-cost.owner=' + f.journal.token]), '');
  assert.equal(docker(['network', 'ls', '-q', '--filter', 'label=io.waitron.cloud-cost.owner=' + f.journal.token]), '');
}

// Omitting the copy/isolation/replay join, admitting a partial day or returning raw data breaks this journey.
test('isolatedControllerRunsTheGenuineWriterAfterIsolationThenCollectsItsOwnState', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  let result;
  await assert.doesNotReject(async () => { result = await controller.runIsolatedReplay(f); });
  assert.equal(result.costMeasured, false);
  assert.deepEqual(result.admission.replay.counts, { expected: 3, attempted: 3, successful: 3, failed: 0 });
  assert.deepEqual(result.admission.source.counts, { sales: 4, paid: 4, tradingDays: 2, busiest: 3 });
  assert.deepEqual(result.admission.integrity, { ok: true, issues: 0 });
  assert.deepEqual(result.isolation, { blockedConnections: 3, blockedDns: 2, localControl: true });
  assert.deepEqual(result.cleanup, { workerContainers: 0, networks: 0, privateCopies: 0 });
  assert.equal(/PRIVATE_|2026-|\/state|taxId|locationId/.test(JSON.stringify(result)), false);
  const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources;
  const isolated = entries.findIndex(e => e.kind === 'outbound-proof' && e.state === 'ready');
  const copied = entries.findIndex(e => e.kind === 'database-copy' && e.state === 'intent');
  assert.ok(isolated >= 0 && copied > isolated, 'prove effective outbound denial before source-copy intent');
  assert.ok(entries.some(e => e.kind === 'isolated-replay' && e.state === 'removed'));
  clean(f, before);
});

test('isolatedControllerCopyRefusalCollectsThePreparedWorkerAndNetwork', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  const refused = join(f.source, 'refused.db'); writeFileSync(refused, Buffer.alloc(20), { mode: 0o600 });
  const messages = [], began = performance.now();
  await assert.rejects(withOwnershipDiagnostics(() => controller.runIsolatedReplay({ ...f, database: refused }),
    () => readFileSync(f.journal.path, 'utf8'), () => ({ elapsedMilliseconds: performance.now() - began,
      changed: false, signalAborted: false }), text => messages.push(text)), bad);
  assert.equal(messages.length, 1);
  const report = JSON.parse(messages[0].slice('ownership-start-refusal '.length));
  assert.equal(report.journalReadable, true); assert.equal(report.workerStarted, false);
  assert.notEqual(report.lastPreparation, 'unknown');
  for (const privateValue of [f.root, f.source, f.journal.token]) assert.equal(messages[0].includes(privateValue), false);
  const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources;
  assert.ok(entries.some(e => e.kind === 'container' && e.state === 'started'), 'reach isolated setup before the copy refusal');
  assert.ok(entries.some(e => e.kind === 'network' && e.state === 'removed'));
  assert.deepEqual(readFileSync(refused), Buffer.alloc(20)); clean(f, before);
});

test('isolatedControllerRefusesMismatchedSourceCountsAndRemovesPrivateCopies', async t => {
  const f = await fixture(t), before = fingerprint(f.database); f.expected.busiest = 4;
  await assert.rejects(controller.runIsolatedReplay(f), bad); clean(f, before);
});

// Validation must precede side effects; refusing an endpoint after opening source data is too late.
test('isolatedControllerRefusesUnsafeInputWithoutCreatingLocalResources', async t => {
  const original = await fixture(t), before = fingerprint(original.database);
  for (const change of [f => { f.config.localEndpoints.s3 = 'https://aws.amazon.com:443'; },
    f => { f.config.senders.fiscal = 'live'; }, f => { f.image = 'node:26.11.1-slim'; },
    f => { f.windowSeconds = 7201; }, f => { f.replayWindowSeconds = 3601; },
    f => { f.windowSeconds = 0; }, f => { f.replayWindowSeconds = Infinity; },
    f => { f.expected.sales = 0; }, f => { f.expected.paid = 5; },
    f => { f.cadence.factor = 0; }, f => { f.cadence.mode = 'original'; },
    f => { f.originalInventory.timeZone = 'Invalid/Zone'; }, f => { f.locationId = ''; },
    f => { f.signal = {}; }, f => { f.journal.token = '0'.repeat(64); },
    f => { f.codeRoot = f.source; }, f => { f.database = f.root; },
    f => { writeFileSync(join(f.codeRoot, 'runtime.mjs'), 'modified runtime'); }]) {
    const f = structuredClone(original);
    change(f); await assert.rejects(controller.runIsolatedReplay(f), bad);
    assert.equal(JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources, undefined);
    clean(original, before);
  }
});

test('isolatedControllerCancellationAfterWorkerAdmissionCollectsEverything', async t => {
  const f = await fixture(t), before = fingerprint(f.database), abort = new AbortController();
  f.cadence = { mode: 'original', factor: 1 };
  const poll = setInterval(() => {
    const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources ?? [];
    if (entries.some(e => e.kind === 'replay-worker' && e.state === 'started')) abort.abort();
  }, 10);
  try { await assert.rejects(controller.runIsolatedReplay({ ...f, signal: abort.signal }), bad); }
  finally { clearInterval(poll); }
  assert.equal(abort.signal.aborted, true, 'reach the worker before cancelling'); clean(f, before);
});

